<?php
require $argv[1];
use SonataMerchant\AdsGate;
$d=sys_get_temp_dir().'/r6_'.getmypid();mkdir($d);mkdir($d.'/catalog-state');
$c=['account_id'=>'999000111','content_language'=>'sk','feed_label'=>'SK','state_dir'=>$d.'/catalog-state'];
$now=time();$id=AdsGate::identity($c,'P0');
$ctx=['account_id'=>'999000111','content_language'=>'sk','feed_label'=>'SK','channel'=>'ONLINE'];
$reg=['version'=>3,'generated_at'=>gmdate('c',$now),'context'=>$ctx,'hold'=>[],'review'=>[],'ok'=>[]];
$pol=['version'=>3,'generated_at'=>gmdate('c',$now),'context'=>$ctx,'complete'=>true,'products_read'=>1200,'hold'=>(object)[]];
$row=['id'=>'P0','main_root_id'=>1965,'main_category_id'=>1965,'title'=>'Glass slides','product_type'=>'Science','link'=>'https://example.invalid/p','price'=>'25 EUR'];
$reset=function(){foreach(['reg','pol','stats']as$p){$x=new ReflectionProperty(AdsGate::class,$p);$x->setAccessible(true);$x->setValue(null,$p==='stats'?[]:null);}};
$put=function($f,$x){file_put_contents($f,json_encode($x));};
$init=function()use($d,$reg,$pol,$put,$reset){$reset();foreach(glob($d.'/*.json')as$f)unlink($f);$put($d.'/ads-review.json',$reg);$put($d.'/ads-policy.json',$pol);};
$n=0;$fail=0;
$t=function($name,$got,$want)use(&$n,&$fail){$n++;$ok=$got===$want;if(!$ok)$fail++;echo ($ok?'PASS':'FAIL')." $name expected=".json_encode($want)." actual=".json_encode($got)."\n";};
$label=function()use($row,$c){return AdsGate::label($row,$c);};
$init();$t('safe valid control',$label(),'ads_ok');
$init();$p=$pol;$p['complete']='false';$p['products_read']=-1;$put($d.'/ads-policy.json',$p);$t('strict complete boolean and positive coverage',$label(),'ads_review');
$init();$p=$pol;$p['version']=99;$put($d.'/ads-policy.json',$p);$t('unknown future schema rejected',$label(),'ads_review');
$init();$p=['version'=>2,'generated_at'=>gmdate('c'),'hold'=>(object)[]];$put($d.'/ads-policy.json',$p);$t('unbound v2 snapshot requires explicit migration context',$label(),'ads_review');
$init();$put($d.'/alternate.json',['version'=>3,'generated_at'=>gmdate('c'),'context'=>$ctx,'hold'=>[$id=>['x_policy_violation']]]);$label();$c2=$c;$c2['ads_policy_holds_file']=$d.'/alternate.json';$t('cache distinguishes sticky path',AdsGate::label($row,$c2),'ads_hold');
$init();AdsGate::context($c,$now);$later=AdsGate::context($c,$now+4*86400);$t('cached policy expires in long-lived process',AdsGate::decide($row,$c,$later)[0],'ads_review');
$mk=function($n){$o=[];for($i=0;$i<$n;$i++)$o[]=['name'=>'accounts/999000111/products/sk~SK~P'.$i,'offerId'=>'P'.$i,'feedLabel'=>'SK','contentLanguage'=>'sk','productStatus'=>['itemLevelIssues'=>[]]];return $o;};
$client=function($pages){return new class($pages){private $p;private $i=0;function __construct($p){$this->p=$p;}function request($url){return $this->p[min($this->i++,count($this->p)-1)];}};};
$throws=function($fn){try{$fn();return false;}catch(\Throwable $e){return true;}};
$sticky=['version'=>3,'generated_at'=>gmdate('c'),'context'=>$ctx,'hold'=>[$id=>['x_policy_violation']]];
$init();$put($d.'/ads-policy-holds.json',$sticky);$ps=$mk(1200);unset($ps[0]['productStatus']);$err=$throws(function()use($c,$client,$ps){AdsGate::policySweep($c,$client([[200,['products'=>$ps]]]));});$out=json_decode(file_get_contents($d.'/ads-policy-holds.json'),true);$t('missing productStatus cannot release a known hold',$err||isset($out['hold'][$id]),true);
$init();$p=$pol;$gone=AdsGate::identity($c,'GONE');$p['hold']=[$gone=>['x_policy_violation']];$put($d.'/ads-policy.json',$p);AdsGate::policySweep($c,$client([[200,['products'=>$mk(1200)]]]));$reset();$rr=$row;$rr['id']='GONE';$t('migration preserves prior-snapshot unseen hold',AdsGate::label($rr,$c),'ads_hold');
$init();$p=$pol;$p['hold']=[$id=>['x_policy_violation']];$put($d.'/ads-policy.json',$p);$before=file_get_contents($d.'/ads-policy.json');$bad=$c;$bad['ads_policy_holds_file']=$d.'/missing/holds.json';$err=$throws(function()use($bad,$client,$mk){AdsGate::policySweep($bad,$client([[200,['products'=>$mk(1200)]]]));});$t('failed sticky write leaves prior snapshot unchanged',$err&&file_get_contents($d.'/ads-policy.json')===$before,true);
$init();$pages=[[200,['products'=>$mk(1100),'nextPageToken'=>'last']],[200,['unexpected'=>'schema_missing_products']]];$err=$throws(function()use($c,$client,$pages){AdsGate::policySweep($c,$client($pages));});$t('malformed final page cannot claim complete coverage',$err,true);
$init();$put($d.'/ads-policy-holds.json',$sticky);$ps=$mk(1200);$ps[0]['productStatus']['itemLevelIssues']=['invalid scalar issue'];$err=$throws(function()use($c,$client,$ps){AdsGate::policySweep($c,$client([[200,['products'=>$ps]]]));});$out=json_decode(file_get_contents($d.'/ads-policy-holds.json'),true);$t('malformed issue cannot release known hold',$err||isset($out['hold'][$id]),true);
echo ($n-$fail)."/$n PASS; $fail failures\n";$reset();foreach(glob($d.'/*.json')as$f)unlink($f);rmdir($d.'/catalog-state');rmdir($d);exit($fail?1:0);
